@Mixin(value={DebugScreenOverlay.class})
public class DebugScreenOverlayMixin {
    @Inject(method={"getGameInformation"}, at={@At(value="RETURN")})
    private void onGetLeftText(CallbackInfoReturnable<List<String>> cir) {
        List list = (List)cir.getReturnValue();
        SodiumDynamicLights ldl = SodiumDynamicLights.get();
        StringBuilder builder = new StringBuilder("Dynamic Light Sources: ");
        builder.append(ldl.getLightSourcesCount()).append(" (U: ").append(ldl.getLastUpdateCount());
        if (!ldl.config.getDynamicLightsMode().isEnabled()) {
            builder.append(" ; ");
            builder.append(ChatFormatting.RED);
            builder.append("Disabled");
            builder.append(ChatFormatting.RESET);
        }
        builder.append(')');
        list.add(builder.toString());
    }
}

